import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'
import { IntegerColumn, StringColumn, BooleanColumn } from '@servicenow/sdk/core'

Flow(
    {
        $id: Now.ID['687a54cb829740f6bb2a9ddb7032f419'],
        name: 'Example_1_Daily Incident Processor',
        description: `Triggers - Daily
Flow Variables
If 
IfElse
For Each 
Skip Iteration
Set Flow Variables
EndFlow
OOB Action: Look Up Records, Log`,
        flowVariables: {
            normalPriorityCount: IntegerColumn({
                label: 'normalPriorityCount',
                mandatory: true,
            }),
            totalProcessed: IntegerColumn({
                label: 'totalProcessed',
                mandatory: true,
            }),
            processingStatus: StringColumn({
                label: 'processingStatus',
                mandatory: true,
            }),
            highPriorityCount: IntegerColumn({
                label: 'highPriorityCount',
                mandatory: true,
            }),
            shouldContinue: BooleanColumn({
                label: 'shouldContinue',
                mandatory: true,
                default: true,
            }),
        },
    },
    wfa.trigger(
        trigger.scheduled.daily,
        {
            $id: Now.ID['96bd6a7ad88542fea2eb94623c4eedba'],
            annotation: 'Run daily at 8:00 AM to process incidents',
        },
        {
            time: Time(
                {
                    hours: 2,
                    minutes: 30,
                },
                'UTC'
            ),
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['1edb09e184564a89ad77168b13fcbe6d'],
                annotation: 'Log flow execution start',
            },
            {
                log_level: 'info',
                log_message: `Daily Incident Processor started. Querying unassigned incidents...${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
        wfa.flowLogic.setFlowVariables(
            {
                annotation: 'Initialize processing counters and status',
                $id: Now.ID['983e1ade48044cbb8659696d072d0439'],
            },
            wfa.dataPill(_params.flowVariables, 'string'),
            {
                totalProcessed: 0,
                highPriorityCount: 0,
                normalPriorityCount: 0,
                processingStatus: 'STARTED',
                shouldContinue: true,
            }
        )
        const actionInstance_3 = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['f311817831d2456d8dc87a00ae5ec749'],
                annotation: 'Query all unassigned incidents',
            },
            {
                conditions: 'assignment_groupISEMPTY^active=true^ORDERBYpriority',
                table: 'incident',
                sort_type: 'sort_asc',
                sort_column: '',
                max_results: 1000,
            }
        )
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(actionInstance_3.Count, 'integer')}=0`,
                annotation: 'Check if there are incidents to process',
                $id: Now.ID['0c627e4456294872beae75744c2b5694'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['07e41fa4596946449677b96997252c9f'],
                    },
                    {
                        log_level: 'info',
                        log_message: 'No unassigned incidents found in the last 24 hours.',
                    }
                )
                wfa.flowLogic.endFlow({
                    annotation: 'End flow early - no incidents to process',
                    $id: Now.ID['e8d8da55cc30424d9eef50462919b8cd'],
                })
            }
        )
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['591118ecae9b44d682ac472dca1a5d5c'],
            },
            {
                log_level: 'info',
                log_message: `Found ${wfa.dataPill(actionInstance_3.Count, 'integer')} unassigned incidents. Beginning processing...`,
            }
        )
        wfa.flowLogic.forEach(
            wfa.dataPill(actionInstance_3.Records, 'records'),
            {
                annotation: 'Process each unassigned incident',
                $id: Now.ID['46d167c6cead4a7dacc554b3eed6368e'],
            },
            (item_8) => {
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(item_8.priority, 'choice')}=1`,
                        annotation: 'Handle Priority 1 - Critical incidents',
                        $id: Now.ID['00097b978c2644278eb80a4321cc2f51'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['d2829217fc644abdbfc4482656ea18a1'],
                            },
                            {
                                log_level: 'error',
                                log_message: `CRITICAL: Incident  ${wfa.dataPill(item_8.assignment_group, 'reference')}${wfa.dataPill(item_8, 'document_id')}${wfa.dataPill(item_8.priority, 'choice')}
requires immediate attention!`,
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(item_8.priority, 'choice')}=2`,
                        annotation: 'Handle Priority 2 - High priority incidents',
                        $id: Now.ID['d6245c6b9c9442f5a336410138f3ea44'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['4b2d862b4dcb481ea15649dddf0c9004'],
                            },
                            {
                                log_level: 'warn',
                                log_message: `HIGH PRIORITY: Incident  - ${wfa.dataPill(item_8.assignment_group, 'reference')}${wfa.dataPill(item_8.priority, 'choice')}`,
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(item_8.priority, 'choice')}=3`,
                        annotation: 'Handle Priority 3 - Moderate priority',
                        $id: Now.ID['031692437d94496e8ed7e77809138edc'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['816bb8dfdeae4561a9245c58dae6d98b'],
                            },
                            {
                                log_level: 'info',
                                log_message: `Moderate priority incident ${wfa.dataPill(item_8.sys_class_name, 'choice')} identified`,
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(item_8.priority, 'choice')}=4^NQ${wfa.dataPill(item_8.priority, 'choice')}=5`,
                        annotation: 'Else if the Priority is Low or Planning',
                        $id: Now.ID['b565efe3b15af6d0f8774074995d998e'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['46a52b27b15af6d0f8774074995d999a'],
                                uuid: '1e295392-ce77-4d65-8a91-70520406cd9f',
                            },
                            {
                                log_level: 'info',
                                log_message: `Moderate priority incident ${wfa.dataPill(item_8.sys_class_name, 'choice')} identified`,
                            }
                        )
                    }
                )
                wfa.flowLogic.else(
                    {
                        annotation: 'else',
                        $id: Now.ID['79c56f27b15af6d0f8774074995d9973'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['33c5af27b15af6d0f8774074995d99a5'],
                                uuid: '5f22edca-d2cd-4752-b496-6a9e17419d3a',
                            },
                            {
                                log_level: 'info',
                                log_message: 'Exiting loop if priority is not set',
                            }
                        )
                        wfa.flowLogic.exitLoop({
                            annotation: 'exit loop',
                            $id: Now.ID['dee56367b15af6d0f8774074995d9952'],
                        })
                    }
                )
            }
        )
        wfa.flowLogic.setFlowVariables(
            {
                annotation: 'Set processing complete status',
                $id: Now.ID['5a60803f42b647c3bcb8366c91cbc3fa'],
            },
            wfa.dataPill(_params.flowVariables, 'string'),
            {
                processingStatus: 'COMPLETED',
                shouldContinue: false,
            }
        )
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['77ddc9bbeb8c4cceb3d228c9428b115b'],
                annotation: 'Log comprehensive execution summary',
            },
            {
                log_level: 'info',
                log_message: `
=== DAILY INCIDENT PROCESSOR SUMMARY ===
Status: ${wfa.dataPill(_params.flowVariables.processingStatus, 'string')}
Total Incidents Processed: ${wfa.dataPill(_params.flowVariables.totalProcessed, 'integer')}
High Priority (P1/P2): ${wfa.dataPill(_params.flowVariables.highPriorityCount, 'integer')}
Normal/Low Priority (P3/P4): ${wfa.dataPill(_params.flowVariables.normalPriorityCount, 'integer')}
Processing Complete: ${wfa.dataPill(_params.flowVariables.shouldContinue, 'boolean')}
=========================================
                `,
            }
        )
    }
)
